/* 01 tokens */
:root{
  --k-orange:#ff6b00;
  --k-orange-2:#ff8a2a;
  --k-blue:#0b66ff;
  --k-ink:#0b0f16;
  --k-text:#182235;
  --k-muted:#667085;
  --k-soft:#f5f7fb;
  --k-card:#ffffff;
  --k-line:rgba(15,23,42,.10);
  --k-line-strong:rgba(15,23,42,.16);
  --k-shadow:0 18px 55px rgba(15,23,42,.10);
  --k-radius-xl:28px;
  --k-radius-lg:22px;
  --k-radius-md:16px;
  --k-radius-sm:12px;
  --k-page-max:1440px;
  --k-shell-h:76px;
  --k-desktop-sidebar-w:0px;
  --k-mobile-nav-h:72px;
  --k-gap:16px;
  --k-content-cols:4;
  --k-font:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
}

/* 02 base */
*{box-sizing:border-box}
html{min-height:100%;background:#f3f5fa;color:var(--k-text);font-family:var(--k-font)}
body{min-height:100%;margin:0;background:radial-gradient(circle at 12% 0%,rgba(255,107,0,.16),transparent 28%),linear-gradient(180deg,#f8fafc 0%,#eef2f7 100%);color:var(--k-text)}
a{color:inherit;text-decoration:none}
button,input,select,textarea{font:inherit}
button{cursor:pointer}
:focus-visible{outline:3px solid rgba(255,107,0,.35);outline-offset:3px}

/* 03 shell */
.k-app-shell{min-height:100vh;display:block;padding-top:var(--k-shell-h)}
.k-shell-header{position:fixed;top:0;left:0;right:0;width:100%;z-index:80;min-height:var(--k-shell-h);display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:18px;padding:12px clamp(14px,3vw,32px);background:rgba(255,255,255,.94);backdrop-filter:blur(18px);border-bottom:1px solid var(--k-line);box-shadow:0 8px 24px rgba(15,23,42,.06);transform:translate3d(0,0,0);transition:transform .18s ease,box-shadow .18s ease;will-change:transform}
.k-shell-header.is-scroll-hidden{transform:translate3d(0,calc(-100% - 3px),0);box-shadow:none;pointer-events:none}
.k-shell-header.is-scroll-visible{transform:translate3d(0,0,0)}
@media (prefers-reduced-motion:reduce){.k-shell-header{transition:none}}

.k-brand{display:inline-flex;align-items:center;min-width:0}
.k-brand-logo{display:block;object-fit:contain}
.k-brand-logo--full{width:190px;height:50px;object-position:left center}
.k-brand-logo--icon{display:none;width:44px;height:44px;border-radius:13px}
.k-desktop-nav{display:flex;align-items:center;justify-content:center;gap:8px;min-width:0}
.k-nav-link{min-height:42px;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:0 14px;border-radius:999px;color:#344054;font-size:14px;font-weight:850;white-space:nowrap;border:1px solid transparent;transition:background .16s ease,color .16s ease,border-color .16s ease,transform .16s ease}
.k-nav-link:hover{background:rgba(255,107,0,.08);color:#111827}
.k-nav-link.is-active{background:#111827;color:#fff;border-color:#111827;box-shadow:0 10px 24px rgba(17,24,39,.12)}
.k-shell-actions{display:flex;align-items:center;justify-content:flex-end;gap:10px;min-width:0}
.k-page-outlet{width:100%;max-width:var(--k-page-max);margin:0 auto;padding:clamp(18px,3vw,34px) clamp(14px,3vw,28px) calc(var(--k-mobile-nav-h) + 26px);min-width:0}
.k-mobile-nav{position:fixed;left:12px;right:12px;bottom:12px;z-index:60;display:none;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;min-height:var(--k-mobile-nav-h);padding:8px;border:1px solid var(--k-line);border-radius:24px;background:rgba(255,255,255,.92);backdrop-filter:blur(18px);box-shadow:0 18px 55px rgba(15,23,42,.16)}
.k-mobile-nav .k-nav-link{min-height:54px;flex-direction:column;padding:5px 2px;border-radius:18px;font-size:11px;gap:3px}
.k-mobile-nav .k-nav-link .k-nav-icon{font-size:18px;line-height:1}
.k-modal-root,.k-toast-root{position:relative;z-index:100}
.k-desktop-sidebar{display:none}

/* R188.5.5.6.84.111 — shared desktop application shell.
   Desktop uses the same visual system, but a denser composition: rail/sidebar + bounded page container. */
@media (min-width:1024px){
  :root{--k-desktop-sidebar-w:84px;--k-page-max:1440px}
  .k-app-shell{padding-left:var(--k-desktop-sidebar-w)}
  .k-shell-header{grid-template-columns:var(--k-desktop-sidebar-w) minmax(0,1fr) auto;gap:18px;padding:0 24px 0 0}
  .k-shell-header.is-scroll-hidden{transform:none;pointer-events:auto;box-shadow:0 8px 24px rgba(15,23,42,.06)}
  .k-shell-header .k-brand{width:var(--k-desktop-sidebar-w);min-height:var(--k-shell-h);justify-content:center}
  .k-shell-header .k-brand-logo--full{display:none}
  .k-shell-header .k-brand-logo--icon{display:block;width:44px;height:44px}
  .k-shell-actions{display:flex;grid-column:3}
  .k-desktop-sidebar{position:fixed;z-index:70;top:var(--k-shell-h);left:0;bottom:0;display:block;width:var(--k-desktop-sidebar-w);padding:14px 10px 18px;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;background:rgba(255,255,255,.94);border-right:1px solid var(--k-line);box-shadow:8px 0 24px rgba(15,23,42,.035)}
  .k-desktop-nav{display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;gap:6px;width:100%;min-width:0;overflow:visible;padding:0}
  .k-desktop-nav .k-nav-link{position:relative;width:52px;min-height:48px;margin-inline:auto;justify-content:center;gap:0;padding:0;border-radius:14px}
  .k-desktop-nav .k-nav-icon{display:grid;place-items:center;flex:0 0 24px;width:24px;height:24px}
  .k-desktop-nav .k-nav-label{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
  .k-page-outlet{width:min(100%,var(--k-page-max));max-width:var(--k-page-max);padding:32px clamp(24px,2.4vw,36px) 40px}
  .k-mobile-nav{display:none}
}
@media (min-width:1280px){
  :root{--k-desktop-sidebar-w:248px}
  .k-shell-header{padding-right:32px}
  .k-shell-header .k-brand{justify-content:flex-start;padding-left:24px}
  .k-shell-header .k-brand-logo--full{display:block;width:176px;height:48px}
  .k-shell-header .k-brand-logo--icon{display:none}
  .k-desktop-sidebar{padding:16px 14px 22px}
  .k-desktop-nav .k-nav-link{width:100%;min-height:48px;margin:0;justify-content:flex-start;gap:12px;padding:0 14px}
  .k-desktop-nav .k-nav-label{position:static;width:auto;height:auto;margin:0;overflow:visible;clip:auto;white-space:nowrap}
}
@media (max-width:1023px) and (min-width:861px){
  .k-shell-header{grid-template-columns:minmax(0,1fr) auto}
  .k-shell-actions{display:flex}
  .k-desktop-sidebar{display:none}
  .k-mobile-nav{display:grid;left:50%;right:auto;width:min(720px,calc(100vw - 24px));transform:translateX(-50%)}
}

/* 04 layout contracts */
[data-layout="content-grid"]{display:grid;grid-template-columns:repeat(var(--k-content-cols),minmax(0,1fr));gap:var(--k-gap);align-items:stretch}
[data-layout="nav-grid"]{min-width:0}
[data-layout="category-grid"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}
[data-layout="filter-row"]{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
[data-layout="card-layout"]{display:grid;grid-template-columns:48px minmax(0,1fr);gap:12px;align-items:start}
[data-layout="actions-row"]{display:flex;align-items:center;gap:10px;flex-wrap:wrap}

/* 05 components */
.k-page{display:grid;gap:22px;min-width:0}
.k-hero{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(280px,.9fr);gap:22px;align-items:stretch}
.k-panel,.k-card{background:var(--k-card);border:1px solid var(--k-line);border-radius:var(--k-radius-xl);box-shadow:var(--k-shadow);min-width:0}
.k-panel{padding:clamp(18px,3vw,30px)}
.k-card{padding:18px;border-radius:var(--k-radius-lg);display:grid;gap:12px}

.k-title{margin:0;color:var(--k-ink);font-size:clamp(36px,6vw,76px);line-height:.94;letter-spacing:-.07em;font-weight:950}
.k-subtitle{margin:0;max-width:680px;color:var(--k-muted);font-size:16px;line-height:1.48}
.k-section-title{margin:0;color:var(--k-ink);font-size:24px;letter-spacing:-.04em;line-height:1.08}
.k-card h3{margin:0;color:var(--k-ink);font-size:18px;line-height:1.16;letter-spacing:-.03em}
.k-card p{margin:0;color:var(--k-muted);font-size:14px;line-height:1.42}
.k-btn{min-height:44px;display:inline-flex;align-items:center;justify-content:center;gap:8px;border:0;border-radius:15px;background:#111827;color:#fff;padding:0 16px;font-weight:950;white-space:nowrap}
.k-btn.k-btn-primary{background:linear-gradient(135deg,var(--k-orange),var(--k-orange-2));box-shadow:0 14px 26px rgba(255,107,0,.22)}
.k-btn.k-btn-ghost{background:#fff;color:#111827;border:1px solid var(--k-line)}
.k-badge{display:inline-flex;align-items:center;justify-content:center;border-radius:999px;padding:5px 9px;background:#f2f4f7;color:#344054;font-size:12px;font-weight:850}
.k-card-icon{width:48px;height:48px;border-radius:16px;display:inline-flex;align-items:center;justify-content:center;background:rgba(255,107,0,.10);color:var(--k-orange);font-size:21px;font-weight:950}
.k-empty{padding:24px;border:1px dashed var(--k-line-strong);border-radius:var(--k-radius-lg);background:rgba(255,255,255,.58);color:var(--k-muted)}

/* 06 pages */
.k-home-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.k-stat{padding:16px;border-radius:18px;background:#fff;border:1px solid var(--k-line)}
.k-stat b{display:block;color:var(--k-ink);font-size:22px;font-weight:950}
.k-stat span{display:block;color:var(--k-muted);font-size:12px;margin-top:3px}
.k-route-note{font-size:13px;color:#667085}
.k-service-card .k-btn{width:100%}

/* 07 utilities */
.k-hidden{display:none!important}
.k-text-muted{color:var(--k-muted)}
.k-noscript{max-width:720px;margin:40px auto;padding:24px;border-radius:24px;background:#fff;border:1px solid var(--k-line);font-family:var(--k-font)}

/* 08 responsive */
@media (max-width:1100px){
  :root{--k-content-cols:3}
  .k-desktop-nav{justify-content:flex-start;overflow:auto;padding-bottom:2px}
  .k-shell-header{grid-template-columns:auto minmax(0,1fr)}
