  .k-title{font-size:clamp(34px,12vw,54px)}
  .k-home-stats{grid-template-columns:1fr}
  [data-layout="content-grid"]{grid-template-columns:1fr}
  [data-layout="card-layout"]{grid-template-columns:42px minmax(0,1fr)}
}

/* 09 orders domain */
.k-orders-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
