.k-order-card-head,.k-order-card-foot{justify-content:space-between}
.k-order-card-foot strong{margin-left:auto;color:var(--k-ink);font-size:16px}
@media (max-width:980px){.k-orders-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.k-orders-grid{grid-template-columns:1fr}}

