.k-seller-product{display:grid;grid-template-columns:56px minmax(0,1fr) auto;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid var(--k-line)}.k-seller-product:last-child{border-bottom:0}
.k-seller-product-icon{width:56px;height:56px;display:grid;place-items:center;border-radius:16px;background:var(--k-soft);font-size:22px;overflow:hidden}.k-seller-product-icon img{width:100%;height:100%;object-fit:cover}
.k-seller-product-body{display:grid;gap:4px;min-width:0}.k-seller-product-top,.k-seller-product-meta{display:flex;align-items:center;justify-content:space-between;gap:10px}.k-seller-product-top b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.k-seller-product-top span{font-size:11px;font-weight:900;padding:4px 8px;border-radius:99px;background:#ecfdf5;color:#047857}.k-seller-product-body small{color:var(--k-muted)}.k-seller-product-meta strong{color:var(--k-ink)}.k-seller-product-meta em{font-style:normal;color:var(--k-muted);font-size:12px}
