/* r77u: stable mobile rendering and deterministic search/sort toolbars */
.k-page,
.k-app-main,
.k-shell-main,
.k-masters-toolbar,
.k-catalog-toolbar,
.k-orders-search-toolbar,
.k-shop-toolbar {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}

/* Parts toolbar: explicit areas instead of competing inherited grid rules. */
.k-shop-page .k-shop-toolbar {
  display: grid;
  grid-template-columns: minmax(0,1fr) minmax(170px,210px) minmax(120px,160px) 48px auto;
  grid-template-areas: "search sort city filter submit";
  align-items: center;
  gap: 8px;
  width: 100%;
  overflow: visible;
}
.k-shop-page .k-shop-toolbar .k-masters-search { grid-area: search; width: 100%; min-width: 0; }
.k-shop-page .k-shop-toolbar .k-shop-sort { grid-area: sort; width: 100%; min-width: 0; }
.k-shop-page .k-shop-toolbar .k-masters-geo { grid-area: city; min-width: 0; }
.k-shop-page .k-shop-toolbar .k-catalog-filter-wrap { grid-area: filter; min-width: 0; }
.k-shop-page .k-shop-toolbar .k-masters-search-button { grid-area: submit; min-width: 82px; }
.k-shop-page .k-shop-toolbar .k-masters-search input,
.k-shop-page .k-shop-toolbar .k-shop-sort select { min-width: 0; width: 100%; box-sizing: border-box; }

/* Orders toolbar: explicit areas prevent the filter/search button from escaping. */
.k-orders-page .k-orders-search-toolbar,
.k-page.orders .k-orders-search-toolbar {
  display: grid;
  grid-template-columns: minmax(0,1fr) minmax(120px,170px) auto;
  grid-template-areas: "search filter submit";
  align-items: center;
  gap: 8px;
  width: 100%;
  overflow: visible;
}
.k-orders-search-toolbar .k-masters-search { grid-area: search; }
.k-orders-search-toolbar .k-masters-filter-wrap { grid-area: filter; }
.k-orders-search-toolbar .k-masters-search-button { grid-area: submit; }

