/* R149: unified interaction fallback for every Swiper surface. */
.swiper.is-native-fallback{overflow-x:auto!important;overflow-y:hidden;scroll-snap-type:x mandatory;scrollbar-width:none;cursor:grab;touch-action:pan-y pinch-zoom;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch}
.swiper.is-native-fallback::-webkit-scrollbar{display:none}
.swiper.is-native-fallback.is-pointer-down{cursor:grabbing;scroll-snap-type:none;user-select:none;-webkit-user-select:none}
.swiper.is-native-fallback>.swiper-wrapper{display:flex!important;transform:none!important;transition:none!important;width:max-content!important;gap:var(--k-fallback-gap,12px)}
.swiper.is-native-fallback>.swiper-wrapper>.swiper-slide{flex:0 0 var(--k-fallback-slide,min(84vw,360px))!important;width:var(--k-fallback-slide,min(84vw,360px))!important;scroll-snap-align:start;height:auto}
.swiper.is-native-fallback>.swiper-pagination{display:none!important}
