/* R150: unified pointer contract for all Swiper and native fallback sliders. */
.swiper{min-width:0;touch-action:pan-y;overscroll-behavior-x:contain}
.swiper.is-native-fallback,[data-native-horizontal-slider]{overflow-x:auto!important;overflow-y:hidden;scrollbar-width:none;-webkit-overflow-scrolling:touch;cursor:grab;touch-action:pan-y!important;user-select:none}
.swiper.is-native-fallback::-webkit-scrollbar,[data-native-horizontal-slider]::-webkit-scrollbar{display:none}
.swiper.is-native-fallback.is-pointer-down,[data-native-horizontal-slider].is-pointer-down{cursor:grabbing;scroll-snap-type:none!important}
.swiper.is-native-fallback .swiper-wrapper{transform:none!important;transition:none!important}
.swiper.is-native-fallback .swiper-pagination{display:none!important}
.swiper.is-swiper-ready{overflow:hidden}
.swiper.is-swiper-ready .swiper-wrapper{touch-action:pan-y}

/* R151 — slider interaction audit hardening. */
.swiper,.services-home-slider,[data-native-horizontal-slider]{pointer-events:auto}
