/* R186.5 Mobile Navigation Hardening: authoritative final rules */
@media (max-width: 980px) {
  .k-mobile-nav {
    --k-mobile-nav-count: 5;
    display: grid;
    grid-template-columns: repeat(var(--k-mobile-nav-count), minmax(0, 1fr)) !important;
    grid-auto-flow: column;
    grid-auto-rows: 1fr;
    left: max(8px, env(safe-area-inset-left));
    right: max(8px, env(safe-area-inset-right));
    bottom: max(8px, env(safe-area-inset-bottom));
    gap: 4px !important;
    min-height: 68px;
    height: auto;
    padding: 6px !important;
    overflow: visible;
  }
  .k-mobile-nav .k-nav-link {
    min-width: 0;
    min-height: 54px;
    max-width: none;
    padding: 5px 2px !important;
    border: 0;
    background: transparent;
    font: inherit;
    font-size: 10px !important;
    line-height: 1.1;
    overflow: hidden;
  }
  .k-mobile-nav .k-nav-link > span:not(.k-nav-icon) {
    display: block;
    width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: center;
  }
  .k-mobile-nav .k-nav-icon,
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav .k-nav-icon {
    display: grid;
    place-items: center;
    width: 24px !important;
    height: 24px !important;
    margin: 0 auto;
    font-size: 18px !important;
    line-height: 1;
  }
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav,
  html[data-context-type] .k-mobile-nav {
    grid-template-columns: repeat(var(--k-mobile-nav-count), minmax(0, 1fr)) !important;
    gap: 4px !important;
    padding: 6px !important;
  }
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav .k-nav-link {
    font-size: 10px !important;
    padding: 5px 2px !important;
  }
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav .k-nav-icon::before { content: none !important; }
  .k-mobile-nav .k-nav-more { cursor: pointer; color: inherit; }
  .k-mobile-nav .k-nav-more .k-nav-icon { letter-spacing: 2px; font-weight: 800; }
  .k-page-outlet {
    padding-bottom: calc(82px + env(safe-area-inset-bottom)) !important;
  }
}
@media (max-width: 390px) {
  .k-mobile-nav .k-nav-link { font-size: 9px !important; }
  .k-mobile-nav .k-nav-icon { font-size: 17px !important; }
}

/* R186.5 system stability + visual hardening: final authoritative mobile navigation layer. */
@media (max-width: 900px) {
  :root {
    --k-mobile-nav-count: 5;
    --k-mobile-nav-height: calc(70px + env(safe-area-inset-bottom, 0px));
  }
  .k-mobile-nav,
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav,
  html[data-context-type] .k-mobile-nav {
    display: grid;
    grid-template-columns: repeat(var(--k-mobile-nav-count, 5), minmax(0, 1fr)) !important;
    grid-template-rows: 1fr !important;
    left: max(8px, env(safe-area-inset-left, 0px));
    right: max(8px, env(safe-area-inset-right, 0px));
    bottom: max(8px, env(safe-area-inset-bottom, 0px));
    min-height: 62px;
    max-height: var(--k-mobile-nav-height);
    gap: 4px;
    padding: 6px;
    overflow: hidden;
  }
  .k-mobile-nav > *:nth-child(n+7) { display: none !important; }
  .k-mobile-nav .k-nav-link,
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav .k-nav-link {
    min-width: 0;
    min-height: 50px;
    max-width: 100%;
    padding: 5px 2px;
    font-size: clamp(8px, 2.4vw, 10px) !important;
    line-height: 1.15;
    overflow: hidden;
  }
  .k-mobile-nav .k-nav-link > span:not(.k-nav-icon):not(.k-nav-badge) {
    display: block;
    width: 100%;
    max-width: 100%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .k-mobile-nav .k-nav-icon,
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav .k-nav-icon {
    width: 22px;
    height: 22px;
    font-size: 18px !important;
    line-height: 22px;
  }
  .k-mobile-nav .k-nav-icon::before,
  html[data-identity-mode="legacy-fallback"][data-user-role] .k-mobile-nav .k-nav-icon::before { content: none !important; }
  .k-shell-main,
  .k-page { min-width: 0; }
  .k-shell-main { padding-bottom: calc(var(--k-mobile-nav-height) + 18px) !important; }
}

