/* ===== SOURCE: css/next/mobile_back.css ===== */
/* R74q — mobile quick action stack: back above chat. */
.k-mobile-fab-stack,
.k-mobile-fab { display: none; }

@media (max-width: 900px) {
  .k-mobile-fab-stack {
    position: fixed;
    right: 14px;
    bottom: calc(var(--k-mobile-nav-h, 72px) + 20px);
    z-index: 72;
    display: grid;
    gap: 10px;
    justify-items: end;
    pointer-events: none;
  }
  .k-mobile-fab-stack[hidden] { display: none !important; }

  .k-mobile-fab {
    position: relative;
    width: 48px;
    height: 48px;
    place-items: center;
    padding: 0;
    border: 1px solid rgba(17, 24, 39, .12);
    border-radius: 17px;
    background: rgba(255, 255, 255, .97);
    color: #111827;
    box-shadow: 0 14px 36px rgba(15, 23, 42, .18);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    cursor: pointer;
    pointer-events: auto;
    transition: transform .18s ease, box-shadow .18s ease, opacity .18s ease;
  }
  .k-mobile-fab:not([hidden]) { display: grid; }
  .k-mobile-fab svg {
    width: 23px;
    height: 23px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2.1;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  .k-mobile-fab:active { transform: scale(.96); }
  .k-mobile-fab:focus-visible { outline: 3px solid rgba(255,107,0,.28); outline-offset: 3px; }

  .k-mobile-back {
    margin-bottom: 2px;
  }
  .k-mobile-chat {
    background: #111827;
    color: #fff;
    border-color: rgba(255,255,255,.08);
