  align-items: center;
  gap: 12px;
  min-width: 0;
}
.onb2-role-ico-wrap {
  width: 52px;
  height: 52px;
  flex-shrink: 0;
  border-radius: var(--ui-radius-md,10px);
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,107,0,.08);
  border: 1px solid rgba(255,107,0,.18);
}
.onb2-role-ico {
  font-size: 27px;
  line-height: 1;
}
.onb2-role-main {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.onb2-role-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: space-between;
}
.onb2-role-name {
  font-family: 'Oswald', sans-serif;
  font-size: 18px;
  line-height: 1.15;
  font-weight: 700;
  color: var(--text1);
}
.onb2-role-arrow {
  flex-shrink: 0;
  font-size: 18px;
  color: var(--text3);
}
.onb2-role-card.is-selected .onb2-role-arrow,
.onb2-role-card.onb2-role--featured .onb2-role-arrow,
.onb2-role-card.onb2-role--featured .onb2-role-name {
  color: var(--orange);
}
.onb2-role-desc {
  margin: 0;
  font-size: 13px;
  line-height: 1.55;
  color: var(--text2);
}
.onb2-role-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.onb2-role-feat {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--surface-a);
  border: 1px solid var(--line);
  font-size: 11px;
  font-weight: 700;
  color: var(--text2);
  white-space: nowrap;
}
.onb2-role-card.onb2-role--featured {
  border-color: rgba(255,107,0,.28);
}
.onb2-role-badge {
  position: absolute;
  top: -1px;
  right: 14px;
  padding: 2px 8px;
  border-radius: 0 0 var(--ui-radius-sm,5px) var(--ui-radius-sm,5px);
  background: var(--orange);
  color: #fff;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.onb2-desc-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.onb2-desc-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 15px 16px;
  border-radius: var(--ui-radius-lg,18px);
  background: linear-gradient(180deg, color-mix(in srgb, var(--bg2) 95%, white 5%), var(--bg2));
  border: 1px solid var(--line);
}
.onb2-desc-item-ico {
  font-size: 22px;
  line-height: 1;
  margin-top: 2px;
}
.onb2-desc-item-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text1);
  margin-bottom: 3px;
}
.onb2-desc-item-sub {
  font-size: 12px;
  line-height: 1.65;
  color: var(--text2);
}

.onb2-step-note {
  margin-top: 12px;
  text-align: center;
  font-size: 12px;
  color: var(--text3);
}
.onb2-spec-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.onb2-spec-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  min-height: 118px;
  padding: 14px 12px 12px;
  border-radius: var(--ui-radius-lg,18px);
  border: 1.5px solid var(--line);
  background: linear-gradient(180deg, color-mix(in srgb, var(--bg2) 95%, white 5%), var(--bg2));
  box-shadow: 0 10px 22px rgba(0,0,0,.06);
  color: inherit;
  font: inherit;
  text-align: center;
  cursor: pointer;
  transition: border-color .18s ease, background .18s ease, transform .18s ease, box-shadow .18s ease;
}
.onb2-spec-card.is-selected {
  border-color: var(--orange);
  background: rgba(255,107,0,.08);
  box-shadow: 0 14px 26px rgba(255,107,0,.12);
}
.onb2-spec-check {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 20px;
  height: 20px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: transparent;
  color: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
  pointer-events: none;
}
.onb2-spec-card.is-selected .onb2-spec-check {
  background: var(--orange);
  border-color: var(--orange);
  color: #fff;
}
.onb2-spec-ico {
  font-size: 26px;
  line-height: 1;
}
.onb2-spec-body {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.onb2-spec-name {
  font-size: 12px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text1);
}
.onb2-spec-sub {
  font-size: 11px;
  line-height: 1.42;
  color: var(--text2);
}
.onb2-spec-card.is-selected .onb2-spec-name { color: var(--orange); }
.onb2-spec--evac {
  grid-column: 1 / -1;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 12px;
  text-align: left;
  padding: 14px 16px 44px;
  border-color: rgba(239,68,68,.3);
  background: rgba(239,68,68,.06);
}
.onb2-spec--evac .onb2-spec-body { align-items: flex-start; }
.onb2-spec--evac .onb2-spec-name { font-size: 14px; color: #ef4444; }
.onb2-spec--evac .onb2-spec-ico { font-size: 28px; flex-shrink: 0; }
.onb2-spec-evac-badge {
  position: absolute;
  right: 14px;
  bottom: 12px;
  padding: 2px 8px;
  border-radius: 99px;
  background: rgba(239,68,68,.15);
  color: #ef4444;
  border: 1px solid rgba(239,68,68,.25);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.onb2-spec--evac.is-selected {
  border-color: #ef4444;
  background: rgba(239,68,68,.10);
}

.onb2-slider-block { margin-bottom: 0; }
.onb2-slider-label {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text3);
}
.onb2-ip-loading,
.onb2-optional {
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  font-weight: 600;
  color: var(--text3);
}
.onb2-slider-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.onb2-slide-nav {
  width: 34px;
  height: 34px;
  min-width: 34px;
  border-radius: var(--ui-radius-md,10px);
  border: 1px solid var(--line);
  background: var(--surface-a);
  color: var(--text1);
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.onb2-slide-wrap {
  flex: 1;
  overflow: hidden;
}
.onb2-city-track {
  display: flex;
  gap: 8px;
  will-change: transform;
  transition: transform .28s cubic-bezier(.4,0,.2,1);
}
.onb2-city-slide {
  flex-shrink: 0;
  width: clamp(82px, 23vw, 108px);
  min-height: 78px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 10px 6px;
  border-radius: var(--ui-radius-md,10px);
  border: 1.5px solid var(--line);
  background: linear-gradient(180deg, color-mix(in srgb, var(--bg2) 95%, white 5%), var(--bg2));
  opacity: .45;
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition: border-color .18s ease, transform .18s ease, opacity .18s ease, background .18s ease;
}
.onb2-city-slide.is-active {
  opacity: 1;
  border-color: var(--orange);
  background: rgba(255,107,0,.08);
  transform: scale(1.04);
}
.onb2-city-slide.is-side { opacity: .75; }
.onb2-city-slide-title {
  font-family: 'Oswald', sans-serif;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
  color: var(--text1);
}
.onb2-city-slide.is-active .onb2-city-slide-title { color: var(--orange); font-size: 12px; }
.onb2-brand-wrap { overflow-x: auto; }
.onb2-brand-track {
  display: flex;
  gap: 8px;
  padding-bottom: 4px;
  overflow-x: auto;
  scrollbar-width: none;
}
.onb2-brand-track::-webkit-scrollbar { display: none; }
.onb2-brand-slide {
  flex-shrink: 0;
  min-width: 68px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 9px 12px;
  border-radius: var(--ui-radius-md,10px);
  border: 1.5px solid var(--line);
  background: linear-gradient(180deg, color-mix(in srgb, var(--bg2) 95%, white 5%), var(--bg2));
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.onb2-brand-slide.is-selected {
  border-color: var(--orange);
  background: rgba(255,107,0,.08);
}
.onb2-brand-abbr {
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .03em;
  line-height: 1;
  color: var(--text2);
}
.onb2-brand-name {
  font-size: 10px;
  font-weight: 700;
  color: var(--text2);
  white-space: nowrap;
}
.onb2-brand-slide.is-selected .onb2-brand-abbr,
.onb2-brand-slide.is-selected .onb2-brand-name {
  color: var(--orange);
}

.onb2-ip-suggest {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 12px 14px;
  border-radius: var(--ui-radius-md,10px);
  background: rgba(52,211,153,.08);
  border: 1px solid rgba(52,211,153,.22);
}
.onb2-ip-suggest-text,
.onb2-ip-city-label {
  font-size: 13px;
  color: var(--text1);
}
.onb2-ip-city-label { font-weight: 700; }
.onb2-ip-confirm {
  margin-left: auto;
  height: 34px;
  padding: 0 14px;
  border-radius: var(--ui-radius-md,10px);
  border: none;
  background: var(--orange);
  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
.onb2-ip-picked {
  font-size: 13px;
  font-weight: 700;
  color: #34d399;
}

@keyframes onb2-shake {
  0%,100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}
.onb2-shake { animation: onb2-shake .35s ease; }

@media (max-width: 679px) {
  .onb2-headbar { justify-content: flex-start; }
  [data-onb2-profile-preview="desc"],
  [data-onb2-profile-preview="spec"],
  [data-onb2-profile-preview="city"] { display: none !important; }
  .onb2-modal-head {
    padding-top: max(10px, env(safe-area-inset-top, 0px));
    padding-bottom: 14px;
  }
  .onb2-headbar { margin-bottom: 12px; }
  .onb2-brandmark { width: 40px; height: 40px; }
  .onb2-brandtext { font-size: 18px; }
  .onb2-brandsub { font-size: 11px; }
  .onb2-modal-kicker { min-height: 24px; padding: 0 9px; font-size: 10px; }
  .onb2-modal-role-ico { margin-top: 10px; margin-bottom: 6px; font-size: 28px; }
  .onb2-modal-title { font-size: 21px; }
  .onb2-modal-sub { margin-top: 6px; font-size: 12px; line-height: 1.52; }
  .onb2-modal-meta { margin-top: 10px; gap: 6px; }
  .onb2-meta-pill { min-height: 26px; padding: 0 9px; font-size: 10px; }
  .onb2-modal-body {
    padding-top: 12px;
    padding-bottom: 16px;
  }
  .onb2-shell--split,
  .onb2-city-stack { gap: 12px; }
  .onb2-profile-card { padding: 15px; border-radius: var(--ui-radius-lg,18px); }
  .onb2-profile-metrics { grid-template-columns: 1fr; }
  .onb2-role-card { gap: 10px; }
  .onb2-step-note {
    margin-top: 10px;
    font-size: 11px;
    line-height: 1.45;
  }
  .onb2-spec-grid { gap: 6px; }
  .onb2-spec-card {
    min-height: 98px;
    gap: 8px;
    padding: 12px var(--ui-radius-md,10px) var(--ui-radius-md,10px);
    border-radius: var(--ui-radius-md,10px);
  }
  .onb2-spec-check {
    top: 8px;
    right: 8px;
    width: 18px;
    height: 18px;
    font-size: 10px;
  }
  .onb2-spec-ico { font-size: 22px; }
  .onb2-spec-name { font-size: 11px; line-height: 1.24; }
  .onb2-spec--evac {
    gap: 10px;
    padding: 12px 14px 40px;
    border-radius: var(--ui-radius-lg,18px);
  }
  .onb2-spec--evac .onb2-spec-name { font-size: 13px; }
  .onb2-spec--evac .onb2-spec-ico { font-size: 24px; }
  .onb2-spec-evac-badge {
    right: 12px;
    bottom: 10px;
    font-size: 8px;
  }
  .onb2-slider-label { margin-bottom: 8px; font-size: 10px; }
  .onb2-slider-row { gap: 6px; }
  .onb2-slide-nav {
    width: 30px;
    height: 30px;
    min-width: 30px;
    border-radius: var(--ui-radius-md,10px);
    font-size: 16px;
  }
  .onb2-city-slide {
    width: clamp(74px, 22vw, 94px);
    min-height: 68px;
    gap: 4px;
    padding: 8px 6px;
    border-radius: var(--ui-radius-md,10px);
  }
  .onb2-city-slide-title { font-size: 10px; }
  .onb2-city-slide.is-active .onb2-city-slide-title { font-size: 11px; }
  .onb2-brand-track { gap: 6px; }
  .onb2-brand-slide {
    min-width: 60px;
    gap: 3px;
    padding: 8px 10px;
    border-radius: var(--ui-radius-md,10px);
  }
  .onb2-brand-abbr { font-size: 12px; }
  .onb2-brand-name { font-size: 9px; }
  .onb2-ip-suggest {
    gap: 8px;
    padding: 10px 12px;
    border-radius: var(--ui-radius-md,10px);
  }
  .onb2-ip-suggest-text,
  .onb2-ip-city-label,
  .onb2-ip-picked { font-size: 12px; }
  .onb2-ip-confirm {
    width: 100%;
    margin-left: 0;
    justify-content: center;
  }
  .onb2-role-desc,
  .onb2-role-features,
  .onb2-spec-sub,
  .onb2-meta-pill--soft { display: none; }
  .onb2-foot-shell { gap: 8px; }
}

@media (min-width: 680px) {
  .onb2-shell--split {
    grid-template-columns: minmax(280px, 360px) minmax(0, 1fr);
    gap: 18px;
  }
  /* Восстанавливаем profile-preview на планшете */
  .onb2-shell--split [data-onb2-profile-preview] {
    display: block;
  }
  .onb2-role-desc {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    overflow: hidden;
  }
  .onb2-role-features { display: flex; }
  .onb2-role-feat:nth-child(n+3) { display: none; }
  .onb2-spec-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
  .onb2-spec-card { min-height: 150px; padding: 16px 14px; }
  .onb2-spec-sub {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    overflow: hidden;
  }
}

@media (min-width: 1024px) {
  .onb2-modal-head { padding-top: max(20px, env(safe-area-inset-top, 0px)); padding-bottom: 22px; }
  .onb2-shell--split {
    grid-template-columns: minmax(320px, 390px) minmax(0, 1fr);
    gap: 22px;
  }
  .onb2-roles { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
  .onb2-role-card { min-height: 230px; padding: 20px; }
  .onb2-role-desc { -webkit-line-clamp: 4; font-size: 14px; }
  .onb2-role-feat:nth-child(n+3) { display: inline-flex; }
  .onb2-spec-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
  .onb2-spec-card {
    min-height: 172px;
    align-items: flex-start;
    text-align: left;
    padding: 18px 16px 16px;
  }
  .onb2-spec-body { align-items: flex-start; }
  .onb2-spec-name { font-size: 13px; }
  .onb2-spec-sub { -webkit-line-clamp: 3; }
  .onb2-spec--evac {
    grid-column: span 2;
    align-items: flex-start;
    padding-right: 72px;
  }
  .onb2-spec-evac-badge { right: 16px; bottom: 16px; }
}

@media (hover: hover) {
  .onb2-role-card:hover,
  .onb2-spec-card:hover,
  .onb2-city-slide:hover,
  .onb2-brand-slide:hover {
    border-color: rgba(255,107,0,.28);
    transform: translateY(-1px);
  }
}


