  justify-content: center;
  align-items: center;
  padding: 0 18px 8px;
  margin-top: -4px;
}
.onb2-route-chip {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  max-width: 100%;
  padding: 5px 9px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.05);
  color: var(--text3);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
