/* ONBOARDING r66y — canonical role screen branch.
   One source of truth for #onb2-step-role. Historical role-screen variants were removed
   because they redefined the same cards for mobile/tablet/desktop and caused layout drift. */
#onb2-overlay:has(#onb2-step-role.active){
  display:grid;
  place-items:center;
  padding:0;
  background:
    radial-gradient(circle at 50% 10%, rgba(255,255,255,.98), rgba(255,255,255,0) 44%),
    linear-gradient(180deg,#f6f6f7 0%,#ececef 100%);
  backdrop-filter:none;
  -webkit-backdrop-filter:none;
}
#onb2-step-role{
  position:relative;
  width:100%;
  min-height:100dvh;
  display:flex;
  align-items:stretch;
  justify-content:center;
  box-sizing:border-box;
}
#onb2-step-role::after{display:none !important;}
#onb2-step-role .onb2-modal{
  --onb-role-modal-w:430px;
  --onb-role-card-h:116px;
  --onb-role-card-radius:22px;
