  --onb-role-card-pad-x:16px;
  --onb-role-icon:72px;
  --onb-role-name:24px;
  --onb-role-desc:14px;
  --onb-role-gap:14px;
  position:relative;
  width:min(var(--onb-role-modal-w),100%);
  max-width:var(--onb-role-modal-w);
  min-height:100dvh;
  height:100dvh;
  margin:0 auto;
  display:flex;
  flex-direction:column;
  overflow:hidden;
  border:0;
  border-radius:0;
  color:#0c131b;
  background:
    radial-gradient(circle at 50% 18%, rgba(255,255,255,.92), rgba(255,255,255,0) 42%),
    linear-gradient(180deg,#f7f7f8 0%,#efefef 100%);
  box-shadow:0 18px 60px rgba(20,24,32,.12);
  box-sizing:border-box;
}
#onb2-step-role .onb2-modal::before{
  content:'';
  position:absolute;
  inset:0;
  background:linear-gradient(90deg, rgba(0,0,0,.018), rgba(255,255,255,.06) 24%, rgba(0,0,0,.018) 52%, rgba(255,255,255,.06) 82%, rgba(0,0,0,.018));
