  margin:9px 0 0;
  color:#71717a;
  font-size:13px;
  line-height:1.42;
  font-weight:650;
}
.onb-vehicle-visual{
  position:relative;
  min-height:112px;
  margin:16px 0 14px;
  border-radius:22px;
  background:
    radial-gradient(circle at 24% 30%, rgba(255,196,0,.30) 0 28px, transparent 29px),
    linear-gradient(180deg,#f9fafb,#f2f2f3);
  overflow:hidden;
  border:1px solid #e8e8eb;
}
.onb-vehicle-road{
  position:absolute;
  left:0;
  right:0;
  bottom:20px;
  height:24px;
  background:linear-gradient(90deg,transparent,#d9d9df,transparent);
  opacity:.7;
}
.onb-vehicle-car{
  position:absolute;
  left:50%;
  bottom:29px;
  width:158px;
  height:46px;
  transform:translateX(-50%);
}
.onb-vehicle-car i{
  position:absolute;
  left:20px;
  right:20px;
  bottom:10px;
  height:27px;
  border-radius:18px 24px 10px 10px;
  background:#ffc400;
  border:2px solid #111;
}
.onb-vehicle-car b{
  position:absolute;
  left:48px;
  top:1px;
  width:62px;
  height:28px;
  border-radius:22px 22px 6px 6px;
  background:#fff;
  border:2px solid #111;
}
.onb-vehicle-car span:before,
.onb-vehicle-car span:after{
  content:"";
  position:absolute;
  bottom:0;
  width:24px;
  height:24px;
  border-radius:50%;
  background:#111;
  box-shadow:inset 0 0 0 6px #fff;
}
.onb-vehicle-car span:before{left:30px;}
.onb-vehicle-car span:after{right:30px;}
.onb-vehicle-form{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:11px;
}
.onb-vehicle-field{
  display:grid;
  grid-column:1/-1;
  gap:7px;
}
.onb-vehicle-field--half{
  grid-column:auto;
}
.onb-vehicle-field span{
  font-size:12px;
  color:#242424;
  font-weight:900;
}
.onb-vehicle-field input{
  width:100%;
  min-height:45px;
  border:1px solid #e8e8eb;
  border-radius:14px;
  background:#fff;
  color:#111;
  outline:0;
  padding:0 13px;
  font-size:14px;
  font-weight:750;
}
.onb-vehicle-field input::placeholder{
  color:#a1a1aa;
}
.onb-vehicle-note{
  margin:12px 0 0;
  border:1px solid rgba(255,196,0,.44);
  border-radius:16px;
  background:#fff8d7;
  padding:12px 13px;
}
.onb-vehicle-note b{
  display:block;
  color:#111;
  font-size:13px;
  font-weight:950;
}
.onb-vehicle-note span{
  display:block;
  margin-top:4px;
  color:#71717a;
  font-size:11.5px;
  line-height:1.35;
  font-weight:700;
}
.onb-vehicle-error{
  margin-top:10px;
