/* ONBOARDING r66z — isolated reference branches.
   Rule: quick-ref and profile-ref do not share layout/media contracts.
   The generic .onb2-modal--ref block above is only the small-phone skin. */
#onb2-step-quick.active,
#onb2-step-profile.active{
  align-items:stretch;
  justify-content:center;
  box-sizing:border-box;
}
#onb2-step-quick .onb2-modal--quick-ref,
#onb2-step-profile .onb2-modal--profile-ref{
  isolation:isolate;
}
#onb2-step-quick .onb2-ref-status,
#onb2-step-profile .onb2-ref-status{grid-area:status;}
#onb2-step-quick .onb2-ref-topbar,
#onb2-step-profile .onb2-ref-topbar{grid-area:topbar;}
#onb2-step-quick .onb2-ref-footer--quick,
#onb2-step-profile .onb2-ref-footer--profile{
  grid-area:footer;
  position:relative;
  left:auto;
  right:auto;
  bottom:auto;
  z-index:6;
  padding:0 28px 22px;
}

/* Quick reference branch: short form, separate title/lead/avatar/form rows. */
#onb2-overlay:has(#onb2-step-quick.active){
  background:
    radial-gradient(circle at 50% 9%, rgba(255,255,255,.88), rgba(255,255,255,0) 42%),
    linear-gradient(180deg,#f7f7f8 0%,#efeff2 100%);
}
#onb2-step-quick .onb2-modal--quick-ref{
  --onb-ref-cta-bg:linear-gradient(180deg,#20242b 0%,#111827 100%);
  --onb-ref-cta-bg-hover:linear-gradient(180deg,#2b313a 0%,#151d2a 100%);
  display:grid;
  grid-template-rows:auto auto minmax(0,1fr) auto;
  grid-template-areas:"status" "topbar" "body" "footer";
}
#onb2-step-quick .onb2-ref-body--quick{
  grid-area:body;
  display:grid;
  grid-template-columns:1fr;
  grid-template-areas:"title" "lead" "avatar" "form";
