  html[data-user-role="client"] #k-mobile-nav {
    --k-mobile-nav-count: 6 !important;
    grid-template-columns: repeat(6, minmax(0, 1fr)) !important;
    grid-template-rows: 1fr !important;
    gap: 4px !important;
    padding-inline: 6px !important;
  }

  html[data-user-role="client"] #k-mobile-nav .k-nav-link {
    min-width: 0;
    min-height: 52px;
    gap: 2px;
    padding-inline: 1px !important;
  }

  html[data-user-role="client"] #k-mobile-nav .k-nav-link .k-nav-icon,
  html[data-user-role="client"] #k-mobile-nav .k-nav-link .k-nav-icon svg {
    width: 20px;
    height: 20px;
  }

  html[data-user-role="client"] #k-mobile-nav .k-nav-link > span:not(.k-nav-icon):not(.k-nav-badge) {
    min-width: 0;
    max-width: 100%;
