/* ===== SOURCE: css/next/first_vehicle_flow.css ===== */
/* R188.5.5.6.84.36 — First Vehicle: dedicated fullscreen surface, MASTER-aligned header and 3-step confirmation. */
:root{
  --k-fv-orange:#ff4b14;
  --k-fv-orange-soft:#fff0ea;
  --k-fv-text:#181a1d;
  --k-fv-muted:#747a84;
  --k-fv-bg:#fff;
  --k-fv-line:#e0e3e8;
  --k-fv-error:#d92d20;
  --k-fv-success:#2f9b62;
  --k-fv-shadow:0 8px 24px rgba(17,19,21,.07);
}

#k-first-vehicle-layer.k-first-vehicle-page{
  position:fixed!important;
  inset:0!important;
  z-index:11000!important;
  width:100vw!important;
  max-width:none!important;
  height:100dvh!important;
  min-height:100dvh!important;
  margin:0!important;
  padding:0!important;
  overflow-x:hidden!important;
  overflow-y:auto!important;
  overscroll-behavior:contain;
  background:var(--k-fv-bg)!important;
  color:var(--k-fv-text);
  font-family:Manrope,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;
  -webkit-overflow-scrolling:touch;
  isolation:isolate;
}
#k-first-vehicle-layer[hidden]{display:none!important}
html.k-first-vehicle-active,
html.k-first-vehicle-active body{
  width:100%!important;
  height:100%!important;
  min-height:100dvh!important;
  margin:0!important;
  overflow:hidden!important;
}
html.k-first-vehicle-active #k-shell-header,
html.k-first-vehicle-active #k-mobile-nav,
html.k-first-vehicle-active #k-mobile-fab-stack{
  visibility:hidden!important;
  pointer-events:none!important;
}

.k-first-vehicle-shell,
.k-first-vehicle-shell *{box-sizing:border-box}
.k-first-vehicle-shell{
  width:100%;
  min-height:100%;
  margin:0 auto;
  padding:0 0 max(48px,env(safe-area-inset-bottom));
  background:#fff;
}

/* Header intentionally mirrors MASTER First Entry: centered brand + horizontal progress row. */
.k-first-vehicle-header{
  position:sticky;
  top:0;
  z-index:12;
  width:100%;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:calc(7px + env(safe-area-inset-top,0px)) 18px 10px;
  border-bottom:1px solid rgba(224,227,232,.92);
  background:rgba(255,255,255,.98);
  backdrop-filter:blur(16px);
  -webkit-backdrop-filter:blur(16px);
}
.k-first-vehicle-logo{
  display:block;
  width:clamp(150px,42vw,210px);
  height:auto;
  max-height:46px;
  object-fit:contain;
}
.k-first-vehicle-steps{
  width:min(calc(100% - 16px),340px);
  list-style:none;
  margin:0 auto;
  padding:0;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  align-items:start;
}
.k-first-vehicle-steps li{
  position:relative;
  min-width:0;
  display:grid;
  justify-items:center;
  gap:4px;
  color:var(--k-fv-muted);
  font-size:10px;
  font-weight:650;
}
.k-first-vehicle-steps li:not(:last-child)::after{
  content:"";
  position:absolute;
  z-index:0;
  top:13px;
  left:calc(50% + 18px);
  right:calc(-50% + 18px);
  height:2px;
  border-radius:99px;
  background:#e5e7eb;
}
.k-first-vehicle-steps li.is-complete:not(:last-child)::after{background:#ffd8c9}
.k-first-vehicle-steps span{
  position:relative;
  z-index:1;
  width:28px;
  height:28px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:#f2f3f5;
  color:#41454b;
  font-size:13px;
  font-weight:800;
}
.k-first-vehicle-steps .is-active span{background:var(--k-fv-orange);color:#fff}
.k-first-vehicle-steps .is-complete span{background:var(--k-fv-orange-soft);color:var(--k-fv-orange)}
.k-first-vehicle-steps small{
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.k-first-vehicle-steps .is-active small{color:var(--k-fv-text);font-weight:800}

.k-first-vehicle-copy,
.k-first-vehicle-card,
.k-first-vehicle-actions,
.k-first-vehicle-after-hint,
.k-first-vehicle-success{
  width:min(calc(100% - 36px),680px);
}
.k-first-vehicle-copy{margin:30px auto 0}
.k-first-vehicle-copy h1{
  margin:0;
  font-size:24px;
  line-height:30px;
  font-weight:700;
  letter-spacing:-.025em;
}
.k-first-vehicle-copy p{
  margin:8px 0 0;
  color:var(--k-fv-muted);
  font-size:15px;
  line-height:23px;
  font-weight:500;
}
.k-first-vehicle-card{
  margin:20px auto 0;
  padding:20px;
  border:1px solid var(--k-fv-line);
  border-radius:18px;
  background:#fff;
  box-shadow:var(--k-fv-shadow);
}

.k-first-vehicle-intro-card{
  display:grid;
  grid-template-columns:170px minmax(0,1fr);
  align-items:center;
  gap:22px;
}
.k-first-vehicle-illustration{
  height:126px;
  border:1px solid #eceef1;
  border-radius:16px;
  background:#f8f8f9;
  display:grid;
  place-items:center;
  color:#41454b;
}
.k-first-vehicle-illustration svg,
.k-first-vehicle-car-visual svg,
.k-first-vehicle-empty-visual svg{
  fill:none;
  stroke:currentColor;
  stroke-width:2;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.k-first-vehicle-illustration svg{width:118px;height:78px}
.k-first-vehicle-intro-card ul{
  margin:0;
  padding:0;
  list-style:none;
  display:grid;
  gap:11px;
}
.k-first-vehicle-intro-card li{
  position:relative;
  padding-left:22px;
  color:#4f565d;
  font-size:14px;
  line-height:20px;
  font-weight:550;
}
.k-first-vehicle-intro-card li::before{
  content:"";
  position:absolute;
  left:0;
  top:6px;
  width:8px;
  height:8px;
  border:3px solid var(--k-fv-orange);
  border-radius:50%;
}

.k-first-vehicle-actions{
  margin:18px auto 0;
  display:grid;
  gap:8px;
}
.k-first-vehicle-primary{
  width:100%;
  height:52px;
  border:0;
  border-radius:14px;
  background:linear-gradient(135deg,#ff5218,#ff3d0a);
  color:#fff;
  font:600 16px/22px inherit;
  padding:0 20px;
  cursor:pointer;
  box-shadow:0 8px 20px rgba(255,75,20,.18);
}
.k-first-vehicle-primary:disabled{
  background:#eceef1;
  color:#a2a7af;
  cursor:not-allowed;
  box-shadow:none;
}
.k-first-vehicle-primary:not(:disabled):active{transform:translateY(1px)}
.k-first-vehicle-secondary{
  width:100%;
  min-height:46px;
  border:0;
  border-radius:12px;
  background:transparent;
  color:var(--k-fv-muted);
  font:600 14px/20px inherit;
  cursor:pointer;
}
.k-first-vehicle-secondary:hover{background:#f8f8f9}
.k-first-vehicle-secondary.is-bordered{
  border:1px solid var(--k-fv-line);
  background:#fff;
  color:var(--k-fv-text);
}

.k-first-vehicle-form{display:grid;gap:12px}
.k-first-vehicle-form label{
  display:grid;
  gap:6px;
  color:var(--k-fv-text);
  font-size:12.5px;
  font-weight:600;
}
.k-first-vehicle-form label>span b{color:var(--k-fv-orange)}
.k-first-vehicle-form input,
.k-first-vehicle-form select{
  width:100%;
  height:50px;
  border:1px solid var(--k-fv-line);
  border-radius:14px;
  background:#fff;
  color:var(--k-fv-text);
  padding:0 14px;
  font:500 15px/22px inherit;
  outline:none;
}
.k-first-vehicle-form input:focus,
.k-first-vehicle-form select:focus{
  border-color:var(--k-fv-orange);
  box-shadow:0 0 0 4px rgba(255,75,20,.14);
}
.k-first-vehicle-form input.is-invalid,
.k-first-vehicle-form select.is-invalid{
  border-color:var(--k-fv-error);
  box-shadow:0 0 0 4px rgba(217,45,32,.1);
}
.k-first-vehicle-form input:disabled{background:#f8f8f9;color:#9a9ea3;cursor:not-allowed}
.k-first-vehicle-form-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.k-first-vehicle-error{
  min-height:0;
  color:var(--k-fv-error);
  font-size:11.5px;
  line-height:17px;
  font-weight:600;
}
.k-first-vehicle-error:empty{display:none}
.k-first-vehicle-field-note{color:#8a9096;font-size:11px;line-height:16px;font-weight:500}
.k-first-vehicle-hint{margin:2px 0 0;color:var(--k-fv-muted);font-size:12px;line-height:18px}
.k-first-vehicle-unit-field{position:relative}
.k-first-vehicle-unit-field input{padding-right:48px}
.k-first-vehicle-unit-field i{
  position:absolute;
  right:15px;
  top:50%;
  transform:translateY(-50%);
  font-style:normal;
  color:var(--k-fv-muted);
  font-size:13px;
  font-weight:650;
}

.k-first-vehicle-review{position:relative}
.k-first-vehicle-review-card{
  display:grid;
  grid-template-columns:116px minmax(0,1fr);
  gap:18px;
  align-items:center;
}
.k-first-vehicle-car-visual{
  grid-row:1/5;
  width:116px;
  height:92px;
  border:1px solid #e8eaee;
  border-radius:16px;
  background:#f8f8f9;
  display:grid;
  place-items:center;
  color:#3f444a;
}
.k-first-vehicle-car-visual svg{width:94px;height:64px}
.k-first-vehicle-review-head{
  display:flex;
  justify-content:space-between;
  gap:12px;
  align-items:flex-start;
}
.k-first-vehicle-review-head h2{margin:0;font-size:18px;line-height:24px;font-weight:750}
.k-first-vehicle-review-head p{margin:3px 0 0;color:var(--k-fv-muted);font-size:13px}
.k-first-vehicle-review-head>b{
  flex:0 0 auto;
  border-radius:999px;
  background:var(--k-fv-orange-soft);
  color:var(--k-fv-orange);
  padding:6px 9px;
  font-size:10px;
  font-weight:800;
}
.k-first-vehicle-review-meta{margin:6px 0 0;color:#4f565d;font-size:14px;font-weight:550}
.k-first-vehicle-edit{
  position:absolute;
  right:18px;
  bottom:16px;
  border:0;
  background:transparent;
  color:var(--k-fv-orange);
  font:700 13px/18px inherit;
  cursor:pointer;
}
.k-first-vehicle-after-hint{margin:11px auto 0;color:var(--k-fv-muted);font-size:12px}
.k-first-vehicle-submit-error{
  min-height:18px;
  color:var(--k-fv-error);
  text-align:center;
  font-size:12px;
  font-weight:600;
}

.k-first-vehicle-success{
  margin:26px auto 0;
  text-align:center;
}
.k-first-vehicle-success-icon{
  width:64px;
  height:64px;
  margin:0 auto 14px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:#eaf7f0;
  color:var(--k-fv-success);
}
.k-first-vehicle-success-icon svg{
  width:34px;
  height:34px;
  fill:none;
  stroke:currentColor;
  stroke-width:1.9;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.k-first-vehicle-success h1{margin:0;font-size:24px;line-height:30px}
.k-first-vehicle-success>p{margin:7px 0 0;color:var(--k-fv-muted);font-size:15px}
.k-first-vehicle-success .k-first-vehicle-review-card{
  margin-top:20px;
  padding:18px;
  border:1px solid var(--k-fv-line);
  border-radius:18px;
  background:#fff;
  box-shadow:var(--k-fv-shadow);
  text-align:left;
}

.k-first-vehicle-empty{
  width:min(100%,680px);
  margin:34px auto;
  padding:38px 24px;
  border:1px solid var(--k-fv-line);
  border-radius:20px;
  background:#fff;
  box-shadow:var(--k-fv-shadow);
  text-align:center;
}
.k-first-vehicle-empty-visual{
  width:180px;
  height:122px;
  margin:0 auto 18px;
  border-radius:18px;
  background:#f8f8f9;
  display:grid;
  place-items:center;
  color:#4d535a;
}
.k-first-vehicle-empty-visual svg{width:126px;height:84px}
.k-first-vehicle-empty>span{
  display:block;
  color:var(--k-fv-orange);
  font-size:10px;
  font-weight:850;
  letter-spacing:.1em;
}
.k-first-vehicle-empty h2{margin:6px 0 0;font-size:22px}
.k-first-vehicle-empty p{
  max-width:520px;
  margin:8px auto 18px;
  color:var(--k-fv-muted);
  font-size:14px;
  line-height:21px;
}
