#k-page-outlet>[data-page="services"] :is(.k-drill-tile,.k-service-card,.k-catalog-card):hover{border-color:rgba(252,101,5,.42);box-shadow:var(--k-flow-shadow-hover)}

/* Screen 3 — Community. */
