.k-flow-community-layout{grid-template-columns:minmax(0,760px) minmax(280px,360px);justify-content:center}
.k-community-page.k-flow-primary-page :is(.k-community-native-section,.k-community-groups,.k-community-feed-tools){margin:0;border-radius:var(--k-flow-radius-lg);box-shadow:none}
