.k-masters-page.k-flow-primary-page{width:min(100%,var(--k-flow-content-max))!important;max-width:var(--k-flow-content-max)!important;margin-inline:auto!important;padding:0 0 110px!important}
.k-masters-page.k-flow-primary-page .k-r84-workspace-head{margin:0;padding:0 0 16px;border-bottom:1px solid var(--k-flow-line);background:transparent}
