.k-masters-page.k-flow-primary-page .k-provider-card{padding:16px;border-color:var(--k-flow-line);border-radius:var(--k-flow-radius);box-shadow:none}
.k-masters-page.k-flow-primary-page .k-provider-card:hover{transform:translateY(-1px);border-color:rgba(252,101,5,.42);box-shadow:var(--k-flow-shadow-hover)}
