/* ===== SOURCE: css/next/client_surface_layout.css ===== */
/* R84.16 — CLIENT page-surface ownership.
   The shared outlet is edge-to-edge only for CLIENT. Each CLIENT page owns its own gutters.
   MASTER/STO/SELLER/ADMIN are intentionally untouched. */
html[data-user-role="client"] {
  --k-client-page-gutter: clamp(12px, 3.8vw, 24px);
}

html[data-user-role="client"] #k-page-outlet {
  width: 100% !important;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
  min-width: 0;
  overflow-x: clip;
}

/* Pages that historically borrowed horizontal spacing from #k-page-outlet.
   Home, Request and Community V2 are excluded because they own their exact K-Flow geometry. */
html[data-user-role="client"] #k-page-outlet > :is(
  .k-page-shell--workspace,
  .k-masters-page.k-flow-primary-page,
  .k-parts-native-page.k-flow-primary-page,
  .k-work-feed-page,
  .k-client-orders-native,
  .k-client-cabinet,
  .k-client-cabinet-page,
  .k-chats-page,
  .k-notifications-page,
  .k-profile-page
) {
  box-sizing: border-box;
  padding-left: var(--k-client-page-gutter) !important;
  padding-right: var(--k-client-page-gutter) !important;
  scroll-padding-inline: var(--k-client-page-gutter);
  margin-bottom: 43px !important;
}

@media (max-width: 359px) {
  html[data-user-role="client"] { --k-client-page-gutter: 12px; }
}

@media (min-width: 600px) {
  html[data-user-role="client"] { --k-client-page-gutter: clamp(20px, 3vw, 32px); }
}

@media (min-width: 1200px) {
  html[data-user-role="client"] { --k-client-page-gutter: 32px; }
