  html[data-user-role="client"] .k-parts-ref-grid{gap:7px!important}
  html[data-user-role="client"] .k-parts-ref-card>footer strong{width:100%!important}
  html[data-user-role="client"] .k-parts-ref-card>footer>div{margin-left:0!important}
  html[data-user-role="client"] [data-page="services"] .k-services-ref-grid{gap:7px!important}
