  html[data-user-role="client"] .k-master-reference-avatar{height:150px!important}

  html[data-user-role="client"] .k-parts-ref-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:12px!important}
  html[data-user-role="client"] [data-page="services"] .k-services-ref-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important}
  html[data-user-role="client"] [data-page="services"] .k-services-ref-services-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}
}

@media(prefers-reduced-motion:reduce){
  html[data-user-role="client"] .k-community-v2 .k-community-feed-tabs{transition:none!important}
}


/* R188.5.5.6.84.60 — mobile navigation readability + content clearance.
   This is intentionally scoped to CLIENT. Active items use a tinted surface so
   white glyphs can never disappear on a white navigation background. */
@media(max-width:900px){
  html[data-user-role="client"]{
    --k-client-nav-active:#ff3b12;
    --k-client-nav-active-soft:#fff1ec;
    --k-client-nav-muted:#6b7280;
  }

  html[data-user-role="client"],
  html[data-user-role="client"] body{
    scroll-padding-bottom:calc(var(--k-client-mobile-nav-clearance) + 20px)!important;
  }

  html[data-user-role="client"] #k-page-outlet{
    padding-bottom:var(--k-client-mobile-nav-clearance)!important;
    scroll-padding-bottom:calc(var(--k-client-mobile-nav-clearance) + 20px)!important;
  }

  html[data-user-role="client"] #k-page-outlet > *{
    scroll-margin-bottom:calc(var(--k-client-mobile-nav-clearance) + 12px)!important;
  }

  html[data-user-role="client"] #k-page-outlet :is(
    input,textarea,select,button,a[href],[tabindex]:not([tabindex="-1"])
  ){
    scroll-margin-bottom:calc(var(--k-client-mobile-nav-clearance) + 18px);
  }

  html[data-user-role="client"] #k-mobile-nav .k-nav-link{
    background:transparent!important;
    border:1px solid transparent!important;
    color:var(--k-client-nav-muted)!important;
    box-shadow:none!important;
    transition:background .16s ease,color .16s ease,border-color .16s ease,transform .16s ease!important;
  }

  html[data-user-role="client"] #k-mobile-nav .k-nav-link:is(.is-active,[aria-current="page"]){
    background:var(--k-client-nav-active-soft)!important;
    border-color:rgba(255,59,18,.10)!important;
    color:var(--k-client-nav-active)!important;
    box-shadow:inset 0 0 0 1px rgba(255,59,18,.035)!important;
    font-weight:750!important;
  }

  html[data-user-role="client"] #k-mobile-nav .k-nav-link:is(.is-active,[aria-current="page"]) .k-nav-icon,
  html[data-user-role="client"] #k-mobile-nav .k-nav-link:is(.is-active,[aria-current="page"]) .k-nav-icon svg{
    color:var(--k-client-nav-active)!important;
    stroke:currentColor!important;
    fill:none!important;
  }

  html[data-user-role="client"] #k-mobile-nav .k-nav-link:is(.is-active,[aria-current="page"]) > span:not(.k-nav-icon):not(.k-nav-badge):not(.k-nav-unread){
    color:var(--k-client-nav-active)!important;
  }

  /* More can be route-active without the sheet being open. Keep that state readable;
     reserve the solid orange surface only for the actually open action hub. */
  html[data-user-role="client"] #k-mobile-nav .k-nav-more[aria-expanded="true"]{
    background:var(--k-client-nav-active)!important;
    border-color:var(--k-client-nav-active)!important;
    color:#fff!important;
    box-shadow:0 7px 18px rgba(255,59,18,.20)!important;
  }
  html[data-user-role="client"] #k-mobile-nav .k-nav-more[aria-expanded="true"] :is(.k-nav-icon,.k-nav-icon svg),
  html[data-user-role="client"] #k-mobile-nav .k-nav-more[aria-expanded="true"] > span:not(.k-nav-icon):not(.k-nav-badge):not(.k-nav-unread){
    color:#fff!important;
    stroke:currentColor!important;
  }

  /* Sticky page controls must sit above the fixed navigation instead of below it. */
  html[data-user-role="client"] body:not(.k-client-keyboard-open) :is(
    .k-flow-request[data-request-flow-version="8"] .k-flow-request-actions,
    .k-request-nav-r78,
    .k-master-ref-booking-continue
  ){
    bottom:calc(var(--k-client-mobile-nav-space) + 8px)!important;
  }

  html[data-user-role="client"] body.k-client-keyboard-open{
    --k-client-mobile-nav-space:0px;
    --k-client-mobile-nav-clearance:16px;
  }
  html[data-user-role="client"] body.k-client-keyboard-open #k-page-outlet{
    padding-bottom:16px!important;
    scroll-padding-bottom:24px!important;
  }
}

/* R188.5.5.6.84.60 — finish active-nav contrast for badges and keyboard focus. */
@media(max-width:900px){
  html[data-user-role="client"] #k-mobile-nav .k-nav-link:is(.is-active,[aria-current="page"]) .k-nav-unread,
  html[data-user-role="client"] #k-mobile-nav .k-nav-link:is(.is-active,[aria-current="page"]) .k-nav-badge{
    box-shadow:0 0 0 2px var(--k-client-nav-active-soft)!important;
  }
  html[data-user-role="client"] #k-mobile-nav .k-nav-more[aria-expanded="true"] :is(.k-nav-unread,.k-nav-badge){
    box-shadow:0 0 0 2px var(--k-client-nav-active)!important;
  }
  html[data-user-role="client"] #k-mobile-nav .k-nav-link:focus-visible{
    outline:2px solid rgba(255,59,18,.42)!important;
    outline-offset:-2px!important;
  }
}


