/* ===== SOURCE: css/next/design_contract.css ===== */
/* KARETA Design Contract v2 — single source of shared visual tokens.
   Role/page files may own layout geometry, but shared visual values must resolve here.
   Legacy --k-ui-* names are compatibility aliases only and must not own values. */
:root{
  /* Existing shared geometry */
  --k-radius-xs:5px;
  --k-radius-control:10px;
  --k-radius-card:18px;
  --k-radius-dialog:24px;

  --k-space-1:4px;
  --k-space-2:8px;
  --k-space-3:12px;
  --k-space-4:16px;
  --k-space-5:20px;
  --k-space-6:24px;
  --k-space-8:32px;

  --k-layout-content-max:1480px;
  --k-layout-page-gutter:clamp(16px,2vw,32px);

  --k-surface-page:#f5f6f8;
  --k-surface-card:#fff;
  --k-line:#e4e7ec;
  --k-text:#111827;
  --k-muted:#667085;
  --k-shadow-card:0 9px 28px rgba(15,23,42,.08);

  /* Canonicalized values that already existed in client_surface_layout.css.
     Kept distinct where merging would change the current UI. */
  --k-layout-page-max:1440px;
  --k-layout-workspace-gutter:clamp(18px,2vw,32px);
  --k-control-height:44px;
  --k-radius-action:12px;
  --k-radius-panel:20px;
  --k-line-soft:#e5e7eb;
  --k-surface-soft:#f7f8fa;
  --k-text-strong:#171a1f;
  --k-muted-ui:#747b84;
  --k-accent:#ff4b0a;
  --k-accent-hover:#e74308;
  --k-shadow-surface:0 8px 24px rgba(15,23,42,.055);

  /* Canonical layer scale */
  --k-z-base:0;
  --k-z-local-raised:3;
  --k-z-sticky:20;
  --k-z-shell:40;
  --k-z-nav:50;
  --k-z-fab:60;
  --k-z-overlay:80;
  --k-z-modal:100;
  --k-z-toast:120;
  --k-z-shell-brand:161;
  --k-z-debug:200;

  /* Temporary compatibility aliases. These names must never receive raw values elsewhere. */
  --k-ui-page-max:var(--k-layout-page-max);
  --k-ui-page-gutter:var(--k-layout-workspace-gutter);
  --k-ui-control-h:var(--k-control-height);
  --k-ui-control-radius:var(--k-radius-action);
  --k-ui-card-radius:var(--k-radius-card);
  --k-ui-panel-radius:var(--k-radius-panel);
  --k-ui-line:var(--k-line-soft);
  --k-ui-soft:var(--k-surface-soft);
  --k-ui-text:var(--k-text-strong);
  --k-ui-muted:var(--k-muted-ui);
  --k-ui-accent:var(--k-accent);
  --k-ui-accent-hover:var(--k-accent-hover);
  --k-ui-shadow:var(--k-shadow-surface);
}

html[data-user-role="master"],
html[data-navigation-context="master"]{
  --k-master-content-max:var(--k-layout-content-max);
